entities:
{
  name: 'user',
  columns: {
    id: {
      type: 'varchar',
      primary: true
    },
    password: {
      type: 'varchar'
    }
  },
  relations: {
    tags: {
      type: 'one-to-many',
      target: 'userTag',
      eager: true,
      cascade: true,
      inverseSide: 'user'
    }
  }
}

{
  name: 'userTag',
  columns: {
    id: {
      type: 'int',
      primary: true,
      generated: true
    },
    name: {
      type: 'varchar'
    },
    start: {
      type: 'date',
      nullable: true
    },
    end: {
      type: 'date',
      nullable: true
    }
  },
  relations: {
    user: {
      type: 'many-to-one',
      target: 'user',
      onDelete: 'CASCADE',
      orphanedRowAction: 'delete',
      inverseSide: 'tags'
    }
  }
}

contents.options:
{
  where: {
    id: system.username || IsNull(),
    tags: {
      start: Raw(alias => `${alias} is null or ${alias} < :current`, {current: new Date()}),
      end: Raw(alias => `${alias} is null or ${alias} > :current`, {current: new Date()})
    }
  }
}
